"""主页面浮层检测与消除。

浮层类型:

- **NEWS** (新闻公告): 登录后可能出现，带「不再显示」复选框
- **SIGN** (每日签到): 登录后可能出现签到奖励弹窗

使用方式::

    from autowsgr.ui.main_page.overlays import detect_overlay, dismiss_overlay

    overlay = detect_overlay(screen)
    if overlay is not None:
        dismiss_overlay(ctrl, overlay)

批次 4.1.1：所有关闭动作都改为「点击 → 验证浮层消失」。限时自动消失的
浮层由 ``click_and_wait_leave_page`` 的轮询覆盖，不再用固定 sleep 死等。
"""

from __future__ import annotations

from typing import TYPE_CHECKING

from autowsgr.image_resources import Templates
from autowsgr.infra.logger import get_logger
from autowsgr.ui._checkers import confirm_dialog_visible
from autowsgr.ui.utils import (
    NavConfig,
    NavigationError,
    click_and_wait_for_page,
    click_and_wait_leave_page,
    wait_for_stable_screen,
    wait_leave_page,
)
from autowsgr.vision import ImageChecker, PixelChecker

from .constants import DismissCoord, OverlayKind, Sig


if TYPE_CHECKING:
    import numpy as np

    from autowsgr.emulator import AndroidController


_log = get_logger('ui')

_SIGN_CONFIRM_MAX: int = 2
"""每日签到最多处理的确认弹窗段数 (领取确认 + 可能的奖励确认)。"""

_SIGN_CONFIRM_TIMEOUT: float = 8.0
"""等待确认弹窗出现的最大时限 (秒)。"""

_CLOSE_CONFIG = NavConfig(
    max_retries=2,
    retry_delay=0.4,
    timeout=2.0,
    interval=0.25,
    stable_frames=1,
)
"""浮层关闭配置：允许一次重试，避免花屏/动画慢导致误判。"""


# ─────────────────────────────────────────────────────────────────────────────
# 检测
# ─────────────────────────────────────────────────────────────────────────────


def detect_overlay(screen: np.ndarray) -> OverlayKind | None:
    """检测截图中是否存在主页面浮层。

    按优先级依次检测: NEWS → SIGN → BOOKING → USER_INFO。

    Returns
    -------
    OverlayKind | None
        检测到的浮层类型，无浮层返回 ``None``。
    """
    page = Templates.MainPage
    if ImageChecker.template_exists(screen, page.NEWS, confidence=0.85):
        _log.debug('[UI] 检测到浮层: 新闻公告')
        return OverlayKind.NEWS
    if ImageChecker.template_exists(screen, page.SIGN, confidence=0.85):
        _log.debug('[UI] 检测到浮层: 每日签到')
        return OverlayKind.SIGN
    if ImageChecker.template_exists(screen, page.BOOKING, confidence=0.85):
        _log.debug('[UI] 检测到浮层: 活动预约')
        return OverlayKind.BOOKING
    if ImageChecker.template_exists(screen, page.USER_INFO, confidence=0.85):
        _log.debug('[UI] 检测到浮层: 提督信息')
        return OverlayKind.USER_INFO
    return None


def _still_overlay(kind: OverlayKind):
    """``wait_leave_page`` checker：目标浮层是否仍在。"""

    def checker(screen: np.ndarray) -> bool:
        return detect_overlay(screen) is kind

    return checker


def _dismiss_by_click(
    ctrl: AndroidController,
    coord: tuple[float, float],
    kind: OverlayKind,
    *,
    source: str,
) -> bool:
    """点击关闭按钮并等待目标浮层消失；失败只 warning，不中断启动。"""
    try:
        click_and_wait_leave_page(
            ctrl,
            coord,
            _still_overlay(kind),
            source=source,
            target=f'{kind.value}关闭',
            config=_CLOSE_CONFIG,
        )
    except NavigationError:
        _log.warning('[UI] {}: 点击后浮层仍在 (已重试)', source)
        return False
    wait_for_stable_screen(
        ctrl,
        timeout=1.0,
        interval=0.12,
        stable_frames=2,
        source=source,
    )
    return True


# ─────────────────────────────────────────────────────────────────────────────
# 消除 — 专用函数
# ─────────────────────────────────────────────────────────────────────────────


def dismiss_news(ctrl: AndroidController, screen: np.ndarray | None = None) -> None:
    """关闭新闻公告浮层。"""
    if screen is None:
        screen = ctrl.screenshot()

    not_show = PixelChecker.check_signature(screen, Sig.NEWS_NOT_SHOW.ps).matched
    if not not_show:
        _log.info('[UI] 新闻公告: 勾选「不再显示」')
        try:
            click_and_wait_for_page(
                ctrl,
                DismissCoord.NEWS_NOT_SHOW.xy,
                lambda current: PixelChecker.check_signature(
                    current, Sig.NEWS_NOT_SHOW.ps
                ).matched,
                source='新闻公告-不再显示',
                target='勾选生效',
                config=NavConfig(
                    max_retries=1,
                    retry_delay=0.0,
                    timeout=1.5,
                    interval=0.2,
                    stable_frames=1,
                ),
            )
        except NavigationError:
            _log.warning('[UI] 新闻公告: 勾选后未确认生效, 继续关闭')

    _log.info('[UI] 新闻公告: 关闭')
    _dismiss_by_click(
        ctrl,
        DismissCoord.NEWS_CLOSE.xy,
        OverlayKind.NEWS,
        source='新闻公告-关闭',
    )


def dismiss_sign(ctrl: AndroidController) -> None:
    """关闭每日签到浮层 (领取奖励 + 处理确认弹窗)。

    签到奖励流程可能包含连续两段确认弹窗:
    1. 点「领取奖励」后弹出「获得 xx」确认弹窗 → 点确认
    2. 部分版本点确认后还有「奖励确认」二级弹窗 → 有则再点

    第一次确认必须点击 (领取后必有), 第二次确认可选 (等不到就直接收尾)。
    确认按钮由 ``confirm_operation`` 自己轮询，这里不再先睡一秒。
    """
    from autowsgr.ui.utils import confirm_operation

    _log.info('[UI] 每日签到: 领取奖励')
    try:
        click_and_wait_for_page(
            ctrl,
            DismissCoord.SIGN_CONFIRM.xy,
            confirm_dialog_visible,
            source='每日签到-领取',
            target='确认弹窗',
            config=NavConfig(
                max_retries=1,
                retry_delay=0.0,
                timeout=2.0,
                interval=0.2,
                stable_frames=1,
            ),
        )
    except NavigationError:
        _log.warning('[UI] 每日签到: 领取后未在短窗口内看到确认弹窗, 交由 confirm_operation 轮询')

    # 第一段确认: 领取后必有, 等待出现并点击 (超时未出现则视为异常)
    confirm_operation(ctrl, must_confirm=True, timeout=_SIGN_CONFIRM_TIMEOUT)
    # 第二段确认: 若还有「奖励确认」弹窗则继续点, 直到画面干净
    for _ in range(_SIGN_CONFIRM_MAX - 1):
        if not confirm_operation(ctrl, must_confirm=False, timeout=_SIGN_CONFIRM_TIMEOUT):
            break
        _log.info('[UI] 每日签到: 二次确认已点击')

    try:
        wait_leave_page(
            ctrl,
            _still_overlay(OverlayKind.SIGN),
            timeout=2.0,
            interval=0.25,
            source='每日签到',
            target='浮层关闭',
        )
    except NavigationError:
        _log.warning('[UI] 每日签到: 确认后签到浮层仍在')
    wait_for_stable_screen(
        ctrl,
        timeout=1.0,
        interval=0.12,
        stable_frames=2,
        source='每日签到',
    )


def dismiss_booking(ctrl: AndroidController) -> None:
    """关闭活动预约浮层。"""
    _log.info('[UI] 活动预约: 关闭')
    _dismiss_by_click(
        ctrl,
        DismissCoord.BOOKING.xy,
        OverlayKind.BOOKING,
        source='活动预约-关闭',
    )


# ─────────────────────────────────────────────────────────────────────────────
# 消除 — 统一分发
# ─────────────────────────────────────────────────────────────────────────────


def dismiss_user_info(ctrl: AndroidController) -> None:
    """关闭提督信息浮层 (全屏个人资料)。"""
    _log.info('[UI] 提督信息: 关闭')
    _dismiss_by_click(
        ctrl,
        DismissCoord.USER_INFO_CLOSE.xy,
        OverlayKind.USER_INFO,
        source='提督信息-关闭',
    )


def dismiss_overlay(ctrl: AndroidController, overlay: OverlayKind) -> None:
    """消除指定类型的浮层。"""
    match overlay:
        case OverlayKind.NEWS:
            dismiss_news(ctrl)
        case OverlayKind.SIGN:
            dismiss_sign(ctrl)
        case OverlayKind.BOOKING:
            dismiss_booking(ctrl)
        case OverlayKind.USER_INFO:
            dismiss_user_info(ctrl)
        case _:
            raise ValueError(f'未知浮层类型: {overlay}')
